// Só segue (para o alerta) se alguma campanha foi pausada por erro de modelo ou de conta nesta rodada.
const pausadas = $input.all().flatMap((i) => Array.isArray(i.json.campanha_pausada) ? i.json.campanha_pausada : []);
if (!pausadas.length) return [];
return [{ json: {
  mensagem: 'O enviador pausou ' + (pausadas.length > 1 ? 'as campanhas' : 'a campanha') + ' '
    + pausadas.map((p) => '#' + p.id + ' "' + p.titulo + '" (' + p.observacao + ')').join('; ')
    + '. Os disparos voltaram para a fila. Corrija o problema e retome com: update campanhas set status = \'em_andamento\' where id = <id>.',
} }];

const d = $input.first().json;
const linha = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const min = Number(d.pausa_min_seg) || 5;
const max = Math.max(min, Number(d.pausa_max_seg) || 20);
const base = { id: d.id, acao: d.acao, tentativas: Number(d.tentativas) || 0, wamid: '', wa_id: '', erro_codigo: '', erro_detalhe: '', devolver: false, pausar: false, pausa: 1 };

if (d.acao === 'enviar') {
  let variaveis = d.variaveis;
  if (typeof variaveis === 'string') { try { variaveis = JSON.parse(variaveis); } catch (e) { variaveis = []; } }
  // Parâmetro de modelo da Meta não aceita quebra de linha nem valor vazio.
  const parametros = (Array.isArray(variaveis) ? variaveis : []).map((v) => ({ type: 'text', text: linha(v).slice(0, 1000) || '-' }));
  return [{ json: {
    ...base,
    status: 'enviando',
    pausa: min + Math.floor(Math.random() * (max - min + 1)),
    phone_number_id: String(d.phone_number_id),
    corpo: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: String(d.telefone).replace(/\D/g, ''),
      type: 'template',
      template: {
        name: d.modelo_nome,
        language: { code: d.modelo_idioma || 'pt_BR' },
        components: parametros.length ? [{ type: 'body', parameters: parametros }] : [],
      },
    },
  } }];
}

const resultados = {
  optout: { status: 'cancelado', erro_detalhe: 'O cliente pediu para não receber mensagens de campanha.' },
  simulado: { status: 'simulado', erro_detalhe: 'Modo teste: telefone fora da lista de teste.' },
  devolver: { status: 'pendente', devolver: true },
  ignorar: { status: 'falhou', erro_detalhe: 'Disparo não encontrado.' },
};
return [{ json: { ...base, ...(resultados[d.acao] || resultados.ignorar) } }];

const prep = $('Preparar envio').first().json;
const r = $input.first().json;
const statusHttp = Number(r.statusCode || 0);
let corpo = r.body;
if (typeof corpo === 'string') { try { corpo = JSON.parse(corpo); } catch (e) { corpo = {}; } }
corpo = corpo || {};
const wamid = corpo.messages?.[0]?.id || '';
const base = { id: prep.id, pausa: prep.pausa, wamid: '', wa_id: '', erro_codigo: '', erro_detalhe: '', devolver: false, pausar: false };

if (statusHttp >= 200 && statusHttp < 300 && wamid) {
  return [{ json: { ...base, status: 'enviado', wamid, wa_id: String(corpo.contacts?.[0]?.wa_id || '') } }];
}

const erro = corpo.error || {};
const codigo = String(erro.code ?? (statusHttp || 'rede'));
const detalhe = [erro.error_user_title || erro.message, erro.error_data?.details || erro.error_user_msg].filter(Boolean).join(' – ')
  || String(r.error?.message || r.message || 'Sem resposta da Meta');
// Problema de configuração (modelo, token, conta, pagamento): devolve à fila sem gastar tentativa e pausa a campanha.
const CONFIGURACAO = ['10', '190', '200', '131005', '131008', '131031', '131042', '133010'];
// Instabilidade ou limite de ritmo: tenta de novo em 15 min, até 3 vezes.
const TRANSITORIO = ['1', '2', '4', '80007', '130429', '131000', '131016', '131048', '131056'];
const configuracao = /^132\d{3}$/.test(codigo) || CONFIGURACAO.includes(codigo) || statusHttp === 401 || statusHttp === 403;
const transitorio = !configuracao && (statusHttp === 0 || statusHttp >= 500 || codigo === 'rede' || TRANSITORIO.includes(codigo));
const res = { ...base, erro_codigo: codigo, erro_detalhe: detalhe.slice(0, 500), pausa: 1 };

if (configuracao) return [{ json: { ...res, status: 'pendente', devolver: true, pausar: true } }];
if (transitorio && prep.tentativas < 3) return [{ json: { ...res, status: 'pendente' } }];
return [{ json: { ...res, status: 'falhou' } }];
